package com.aura.workspace;

import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.net.*;import java.text.*;import java.util.*;

public final class MainActivity extends Activity {
  private LinearLayout body; private TextView state; private String base="",token=""; private int screenVersion=0;
  private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);} private TextView text(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(Color.WHITE);v.setPadding(dp(16),dp(10),dp(16),dp(10));return v;}
  private GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}
  public void onCreate(Bundle b){super.onCreate(b); base=getPreferences(0).getString("url","");token=getPreferences(0).getString("token",""); renderHome();}
  private void root(String title){screenVersion++;ScrollView scroll=new ScrollView(this);LinearLayout all=new LinearLayout(this);all.setOrientation(LinearLayout.VERTICAL);all.setPadding(dp(12),dp(18),dp(12),dp(24));all.setBackgroundColor(Color.rgb(11,17,32));TextView h=text(title,24);h.setTypeface(null,1);all.addView(h);state=text(base.isEmpty()?"Zentrale noch nicht konfiguriert":"Verbundenes Profil: "+base,13);state.setTextColor(Color.rgb(160,190,230));all.addView(state);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);all.addView(body);scroll.addView(all);setContentView(scroll);}
  private Button button(String label,View.OnClickListener click){Button b=new Button(this);b.setText(label);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setBackground(bg(Color.rgb(28,43,70),12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.setMargins(0,dp(7),0,0);body.addView(b,p);b.setOnClickListener(click);return b;}
  private void card(String title,String detail){TextView v=text(title+"\n"+detail,16);v.setBackground(bg(Color.rgb(22,33,56),14));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(8),0,0);body.addView(v,p);}
  private void renderHome(){root("AURA Workspace");card("Enterprise Mobile","Räume, Projekte, Aufgaben, Tickets, Urlaub und Synchronisation");button("Zentrale konfigurieren",v->settings());button("Synchronisieren",v->fetch("/api/v1/sync/changes?cursor=0","Synchronisation"));button("Projekte",v->entityList("Projekte","/api/v1/projects","project"));button("Projekt anlegen / ändern / archivieren",v->projectForm());button("Meine Aufgaben",v->entityList("Aufgaben","/api/v1/tasks","task"));button("Aufgabe anlegen / Status ändern",v->taskForm());button("Helpdesk-Tickets",v->entityList("Helpdesk-Tickets","/api/v1/tickets","ticket"));button("Ticket anlegen / Status ändern",v->ticketForm());button("Räume",v->entityList("Räume","/api/v1/rooms","room"));button("Raum anlegen / ändern / archivieren",v->roomForm());button("Meine Urlaubsanträge",v->leaveRequests());button("Urlaubsantrag einreichen",v->leaveForm());}
  private EditText field(String hint){EditText f=new EditText(this);f.setHint(hint);f.setTextColor(Color.WHITE);f.setHintTextColor(Color.LTGRAY);body.addView(f);return f;}
  private void taskForm(){root("Aufgabe");EditText id=field("Aufgaben-ID (nur für Statusänderung)");EditText title=field("Titel (für neue Aufgabe)");EditText department=field("Fachbereich");EditText assignee=field("Mitarbeiter-ID");assignee.setInputType(2);EditText priority=field("Priorität: Niedrig, Mittel, Hoch, Kritisch");priority.setText("Mittel");button("Aufgabe anlegen",v->{try{long owner=Long.parseLong(assignee.getText().toString());String p=priority.getText().toString();if(title.getText().length()==0||department.getText().length()==0||owner<=0)throw new IllegalArgumentException("Titel, Fachbereich und Mitarbeiter-ID sind Pflicht.");post("/api/v1/tasks","{\"title\":\""+esc(title.getText().toString())+"\",\"department\":\""+esc(department.getText().toString())+"\",\"priority\":\""+esc(p)+"\",\"assigneeId\":"+owner+"}","Aufgabe");}catch(Exception x){state.setText(x.getMessage());}});button("Status ändern",v->{if(id.getText().length()==0){state.setText("Für die Statusänderung ist die Aufgaben-ID erforderlich.");return;}taskStatusPicker(s->post("/api/v1/tasks/"+esc(id.getText().toString())+"/status","{\"status\":\""+s+"\"}","Aufgabenstatus"));});button("Zurück",v->renderHome());}
  private void projectForm(){root("Projektverwaltung");TextView n=text("Für Bearbeiten oder Archivieren die Projekt-ID aus der Projektübersicht eintragen.",14);body.addView(n);EditText id=field("Projekt-ID (für Bearbeiten/Archivieren)");EditText name=field("Projektname");EditText department=field("Fachbereich");EditText description=field("Beschreibung");EditText status=field("Status: planned, active, on_hold, completed, cancelled");status.setText("planned");EditText owner=field("Eigentümer-Mitarbeiter-ID");owner.setInputType(2);button("Projekt anlegen",v->projectRequest("POST","/api/v1/projects",name,department,description,status,owner,false));button("Projekt speichern",v->{if(id.getText().length()==0){state.setText("Für das Speichern ist die Projekt-ID erforderlich.");return;}projectRequest("PUT","/api/v1/projects/"+esc(id.getText().toString()),name,department,description,status,owner,true);});button("Projekt archivieren",v->{if(id.getText().length()==0){state.setText("Für das Archivieren ist die Projekt-ID erforderlich.");return;}request("POST","/api/v1/projects/"+esc(id.getText().toString())+"/archive","","Projekt archivieren");});button("Zurück",v->renderHome());}
  private void projectRequest(String method,String path,EditText name,EditText department,EditText description,EditText status,EditText owner,boolean ownerRequired){try{long employee=owner.getText().length()==0?0:Long.parseLong(owner.getText().toString());if(name.getText().length()==0||department.getText().length()==0||(ownerRequired&&employee<=0))throw new IllegalArgumentException("Name und Fachbereich sind Pflicht; beim Bearbeiten auch die Eigentümer-ID.");request(method,path,"{\"name\":\""+esc(name.getText().toString())+"\",\"department\":\""+esc(department.getText().toString())+"\",\"description\":\""+esc(description.getText().toString())+"\",\"status\":\""+esc(status.getText().toString())+"\",\"ownerId\":"+employee+"}","Projekt");}catch(Exception x){state.setText(x.getMessage());}}
  private void ticketForm(){root("Helpdesk-Ticket");EditText id=field("Ticket-ID (nur für Statusänderung)");EditText title=field("Titel (für neues Ticket)");EditText category=field("Kategorie (z. B. IT, Facility)");EditText priority=field("Priorität: Niedrig, Mittel, Hoch, Kritisch");priority.setText("Mittel");EditText assignee=field("Mitarbeiter-ID (optional)");assignee.setInputType(2);button("Ticket anlegen",v->{try{long owner=assignee.getText().length()==0?0:Long.parseLong(assignee.getText().toString());if(title.getText().length()==0||category.getText().length()==0)throw new IllegalArgumentException("Titel und Kategorie sind Pflicht.");post("/api/v1/tickets","{\"title\":\""+esc(title.getText().toString())+"\",\"category\":\""+esc(category.getText().toString())+"\",\"priority\":\""+esc(priority.getText().toString())+"\",\"assigneeId\":"+owner+"}","Ticket");}catch(Exception x){state.setText(x.getMessage());}});button("Status ändern",v->{if(id.getText().length()==0){state.setText("Für die Statusänderung ist die Ticket-ID erforderlich.");return;}statusPicker("Ticket-Status",s->post("/api/v1/tickets/"+esc(id.getText().toString())+"/status","{\"status\":\""+s+"\"}","Ticket-Status"));});button("Zurück",v->renderHome());}
  private void roomForm(){root("Raumverwaltung");TextView n=text("Für Bearbeiten oder Archivieren die Raum-ID aus der Raumübersicht eintragen.",14);body.addView(n);EditText id=field("Raum-ID (für Bearbeiten/Archivieren)");EditText name=field("Raumname");EditText location=field("Standort");EditText capacity=field("Kapazität");capacity.setInputType(2);EditText equipment=field("Ausstattung");button("Raum anlegen",v->roomRequest("POST","/api/v1/rooms",name,location,capacity,equipment));button("Raum speichern",v->{if(id.getText().length()==0){state.setText("Für das Speichern ist die Raum-ID erforderlich.");return;}roomRequest("PUT","/api/v1/rooms/"+esc(id.getText().toString()),name,location,capacity,equipment);});button("Raum archivieren",v->{if(id.getText().length()==0){state.setText("Für das Archivieren ist die Raum-ID erforderlich.");return;}request("POST","/api/v1/rooms/"+esc(id.getText().toString())+"/archive","","Raum archivieren");});button("Zurück",v->renderHome());}
  private void roomRequest(String method,String path,EditText name,EditText location,EditText capacity,EditText equipment){try{int seats=Integer.parseInt(capacity.getText().toString());if(name.getText().length()==0||location.getText().length()==0||seats<1)throw new IllegalArgumentException("Name, Standort und positive Kapazität sind Pflicht.");request(method,path,"{\"name\":\""+esc(name.getText().toString())+"\",\"location\":\""+esc(location.getText().toString())+"\",\"capacity\":"+seats+",\"equipment\":\""+esc(equipment.getText().toString())+"\"}","Raum");}catch(Exception x){state.setText(x.getMessage());}}
  private void statusPicker(String title,final StatusCallback action){new AlertDialog.Builder(this).setTitle(title).setItems(new String[]{"open","in_progress","resolved","closed"},(d,w)->action.set(new String[]{"open","in_progress","resolved","closed"}[w])).show();}
  private void taskStatusPicker(final StatusCallback action){new AlertDialog.Builder(this).setTitle("Aufgabenstatus").setItems(new String[]{"open","in_progress","done","cancelled"},(d,w)->action.set(new String[]{"open","in_progress","done","cancelled"}[w])).show();}
  private interface StatusCallback{void set(String status);}
  private EditText dateTimeField(String hint){EditText f=field(hint);f.setFocusable(false);f.setClickable(true);f.setInputType(0);f.setOnClickListener(v->{Calendar c=Calendar.getInstance();new DatePickerDialog(this,(view,year,month,day)->new TimePickerDialog(this,(timeView,hour,minute)->{Calendar selected=Calendar.getInstance();selected.set(year,month,day,hour,minute,0);selected.set(Calendar.MILLISECOND,0);f.setText(new SimpleDateFormat("dd.MM.yyyy HH:mm",Locale.GERMANY).format(selected.getTime()));},c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE),true).show(),c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();});return f;}
  private long leaveTimestamp(EditText field) throws ParseException{String value=field.getText().toString().trim();if(value.isEmpty())throw new IllegalArgumentException("Bitte Beginn und Ende über die Datum-/Uhrzeit-Auswahl festlegen.");SimpleDateFormat format=new SimpleDateFormat("dd.MM.yyyy HH:mm",Locale.GERMANY);format.setLenient(false);return format.parse(value).getTime()/1000L;}
  private void leaveForm(){root("Urlaubsantrag");TextView note=text("Beginn und Ende über die Datum- und Uhrzeitauswahl festlegen. Die App rechnet intern um; die Identität wird ausschließlich aus dem Server-Token abgeleitet.",14);body.addView(note);EditText from=dateTimeField("Beginn auswählen");EditText until=dateTimeField("Ende auswählen");EditText reason=field("Grund, z. B. Erholungsurlaub");button("Antrag senden",v->{try{long a=leaveTimestamp(from);long e=leaveTimestamp(until);if(reason.getText().toString().trim().isEmpty())throw new IllegalArgumentException("Bitte einen Grund angeben.");if(e<=a)throw new IllegalArgumentException("Ende muss nach Beginn liegen.");post("/api/v1/leave-requests","{\"startsAt\":"+a+",\"endsAt\":"+e+",\"reason\":\""+esc(reason.getText().toString())+"\"}","Urlaubsantrag");}catch(Exception x){state.setText(x.getMessage());}});button("Zurück",v->renderHome());}
  private String leaveStatus(String status){if("approved".equals(status))return "✓ Genehmigt";if("rejected".equals(status))return "✕ Abgelehnt";return "● Antrag offen";}
  private String leaveDate(long seconds){return new SimpleDateFormat("dd.MM.yyyy HH:mm",Locale.GERMANY).format(new Date(seconds*1000L));}
  private String entityDetail(JSONObject item,String kind){String id="ID: "+item.optString("id","")+"\n";if("project".equals(kind))return id+"Fachbereich: "+item.optString("department","")+"\nStatus: "+item.optString("status","")+"\nBeschreibung: "+item.optString("description","")+"\nEigentümer-ID: "+item.optLong("ownerId",0);if("task".equals(kind))return id+"Fachbereich: "+item.optString("department","")+"\nPriorität: "+item.optString("priority","")+"\nStatus: "+item.optString("status","")+"\nMitarbeiter-ID: "+item.optLong("assigneeId",0);if("ticket".equals(kind))return id+"Kategorie: "+item.optString("category","")+"\nPriorität: "+item.optString("priority","")+"\nStatus: "+item.optString("status","")+"\nMitarbeiter-ID: "+item.optLong("assigneeId",0);return id+"Standort: "+item.optString("location","")+"\nKapazität: "+item.optInt("capacity",0)+"\nAusstattung: "+item.optString("equipment","")+"\nStatus: "+(item.optBoolean("active",true)?"Aktiv":"Archiviert");}
  private String entityTitle(JSONObject item,String kind){if("room".equals(kind))return item.optString("name","Raum");return item.optString("title",item.optString("name",kind));}
  private void entityList(String title,String path,String kind){root(title);state.setText("Aktualisiere Daten über die Zentrale …");new Thread(()->{try{if(base.isEmpty()||token.isEmpty())throw new IOException("Zentrale und Token zuerst konfigurieren.");HttpURLConnection c=(HttpURLConnection)new URL(base+path).openConnection();c.setRequestProperty("Authorization","Bearer "+token);c.setConnectTimeout(10000);c.setReadTimeout(15000);int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();if(in!=null){byte[] buf=new byte[4096];for(int n;(n=in.read(buf))>=0;)out.write(buf,0,n);}String response=out.toString("UTF-8");if(code<200||code>=300)throw new IOException("Serverantwort HTTP "+code+": "+response);JSONArray items=new JSONArray(response);runOnUiThread(()->{state.setText("Aktualisiert: "+items.length()+" Eintrag/Einträge");if(items.length()==0)card("Keine Einträge","Für Ihre Berechtigung liegen derzeit keine Einträge vor.");for(int i=0;i<items.length();i++){try{JSONObject item=items.getJSONObject(i);card(entityTitle(item,kind),entityDetail(item,kind));}catch(JSONException ignored){}}button("Aktualisieren",v->entityList(title,path,kind));button("Zurück",v->renderHome());});}catch(Exception e){runOnUiThread(()->{state.setText("Daten konnten nicht geladen werden");card("Fehler",e.getMessage()==null?e.toString():e.getMessage());button("Erneut versuchen",v->entityList(title,path,kind));button("Zurück",v->renderHome());});}}).start();}
  private void leaveRequests(){root("Meine Urlaubsanträge");final int currentScreen=screenVersion;state.setText("Aktualisiere Status über die Zentrale …");new Thread(()->{try{if(base.isEmpty()||token.isEmpty())throw new IOException("Zentrale und Token zuerst konfigurieren.");HttpURLConnection c=(HttpURLConnection)new URL(base+"/api/v1/leave-requests").openConnection();c.setRequestProperty("Authorization","Bearer "+token);c.setConnectTimeout(10000);c.setReadTimeout(15000);int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();if(in!=null){byte[] buf=new byte[4096];for(int n;(n=in.read(buf))>=0;)out.write(buf,0,n);}String response=out.toString("UTF-8");if(code<200||code>=300)throw new IOException("Serverantwort HTTP "+code+": "+response);JSONArray leaves=new JSONArray(response);runOnUiThread(()->{if(screenVersion!=currentScreen)return;state.setText("Aktualisiert: "+leaves.length()+" Antrag/Anträge • automatische Aktualisierung alle 30 Sekunden");if(leaves.length()==0)card("Keine Urlaubsanträge","Es liegen derzeit keine Anträge für Ihre angemeldete Identität vor.");for(int i=0;i<leaves.length();i++){try{JSONObject leave=leaves.getJSONObject(i);String detail=leaveDate(leave.optLong("startsAt"))+" bis "+leaveDate(leave.optLong("endsAt"))+"\nGrund: "+leave.optString("reason","")+"\nStatus: "+leaveStatus(leave.optString("status","pending"));if(leave.optLong("decidedBy",0)>0)detail+="\nEntschieden durch Mitarbeiter-ID "+leave.optLong("decidedBy");card("Urlaubsantrag",detail);}catch(JSONException ignored){}}button("Status jetzt aktualisieren",v->leaveRequests());button("Zurück",v->renderHome());new Handler(Looper.getMainLooper()).postDelayed(()->{if(screenVersion==currentScreen)leaveRequests();},30000);});}catch(Exception e){runOnUiThread(()->{if(screenVersion!=currentScreen)return;state.setText("Status konnte nicht geladen werden");card("Fehler",e.getMessage()==null?e.toString():e.getMessage());button("Erneut versuchen",v->leaveRequests());button("Zurück",v->renderHome());});}}).start();}
  private String esc(String value){return value.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n");}
  private void settings(){root("Zentrale konfigurieren");EditText u=new EditText(this);u.setHint("https://aura.example:8787");u.setText(base);u.setTextColor(Color.WHITE);u.setHintTextColor(Color.LTGRAY);body.addView(u);EditText t=new EditText(this);t.setHint("Bearer-Token");t.setText(token);t.setInputType(129);t.setTextColor(Color.WHITE);t.setHintTextColor(Color.LTGRAY);body.addView(t);button("Profil speichern",v->{base=u.getText().toString().trim();token=t.getText().toString().trim();getPreferences(0).edit().putString("url",base).putString("token",token).apply();renderHome();});button("Zurück",v->renderHome());}
  private void fetch(String path,String title){root(title);state.setText("Lade zentralen Stand …");new Thread(()->{try{if(base.isEmpty()||token.isEmpty())throw new IOException("Zentrale und Token zuerst konfigurieren.");HttpURLConnection c=(HttpURLConnection)new URL(base+path).openConnection();c.setRequestProperty("Authorization","Bearer "+token);c.setConnectTimeout(10000);c.setReadTimeout(15000);int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];for(int n;(n=in.read(buf))>=0;)out.write(buf,0,n);String response=out.toString("UTF-8");runOnUiThread(()->{state.setText("HTTP "+code);card("Serverantwort",response.length()>12000?response.substring(0,12000)+"…":response);button("Zurück",v->renderHome());});}catch(Exception e){runOnUiThread(()->{state.setText("Synchronisation fehlgeschlagen");card("Fehler",e.getMessage()==null?e.toString():e.getMessage());button("Zurück",v->renderHome());});}}).start();}
  private void post(String path,String json,String title){request("POST",path,json,title);}
  private void request(String method,String path,String json,String title){root(title);state.setText("Sende …");new Thread(()->{try{if(base.isEmpty()||token.isEmpty())throw new IOException("Zentrale und Token zuerst konfigurieren.");HttpURLConnection c=(HttpURLConnection)new URL(base+path).openConnection();c.setRequestMethod(method);c.setDoOutput(true);c.setRequestProperty("Authorization","Bearer "+token);if(!json.isEmpty()){c.setRequestProperty("Content-Type","application/json");c.getOutputStream().write(json.getBytes("UTF-8"));}int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();if(in!=null){byte[] b=new byte[4096];for(int n;(n=in.read(b))>=0;)out.write(b,0,n);}String response=out.toString("UTF-8");runOnUiThread(()->{state.setText("HTTP "+code);card("Serverantwort",response.isEmpty()?"Vorgang erfolgreich abgeschlossen.":response);button("Startseite",v->renderHome());});}catch(Exception e){runOnUiThread(()->{state.setText("Senden fehlgeschlagen");card("Fehler",e.getMessage()==null?e.toString():e.getMessage());button("Zurück",v->renderHome());});}}).start();}
}
